 * the fix is to paste the theme's function body over the one below.
 */

if ( ! defined( 'SN_EDITORIAL_CONVENTION_KINDS' ) ) {
	define( 'SN_EDITORIAL_CONVENTION_KINDS', array( 'pattern', 'block_style', 'class_convention', 'dynamic_block', 'idiom' ) );
}

if ( ! function_exists( 'sn_theme_editorial_conventions' ) ) {
